  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', '+ Fer (sels de) (voie injectable)', 'Lipothymie, voire choc attribué à la libération rapide du fer de sa forme complexe et à la saturation de la sidérophiline.', 'Associations à prendre en compte', '+ Acide acétohydroxamique', 'Diminution de l’absorption digestive de ces deux médicaments par chélation du fer.', 'Associations faisant l''objet de précautions d’emploi', '+ Bictégravir', 'Diminution de près des deux tiers de l’absorption du bictégravir en cas d’ingestion simultanée ou à jeun.', 'Prendre le bictégravir au moins 2 heures avant les sels de fer, ou en même temps qu’un repas.', '+ Bisphophonates', 'Diminution de l''absorption digestive des bisphosphonates.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables sont répertoriés selon la classification de systèmes d’organes MedDRA et énumérés ci-dessous comme : très fréquent (≥ 1/10), fréquent (≥1/100,', 'Fréquent', '(≥ 1/100', 'Peu fréquent', 'Fréquent indéterminée']);
