  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L’association du fondaparinux avec des traitements susceptibles d’accroître le risque hémorragique augmente le risque de saignement (voir rubrique 4.4).', 'Les antiagrégants plaquettaires (acide acétylsalicylique), les AINS (piroxicam) et la digoxine n''ont pas modifié les paramètres pharmacocinétiques du fondaparinux.']);
